import{_ as t,c as i,o as n,a2 as o}from"./chunks/framework.QTfwLiL8.js";const m=JSON.parse('{"title":"GEP-0039: Live Control Plane Migration (Live CPM)","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/community/steering/technical","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/community/steering/technical/0039-live-control-plane-migration.md","to":"0039-live-control-plane-migration.md"},"title":"GEP-0039: Live Control Plane Migration (Live CPM)","prev":false,"next":false},"headers":[],"relativePath":"community/steering/technical/0039-live-control-plane-migration/index.md","filePath":"community/steering/technical/0039-live-control-plane-migration.md","lastUpdated":null}'),r={name:"community/steering/technical/0039-live-control-plane-migration/index.md"};function l(s,e,a,g,u,c){return n(),i("div",null,e[0]||(e[0]=[o('<h1 id="gep-0039-live-control-plane-migration-live-cpm" tabindex="-1">GEP-0039: Live Control Plane Migration (Live CPM) <a class="header-anchor" href="#gep-0039-live-control-plane-migration-live-cpm" aria-label="Permalink to &quot;GEP-0039: Live Control Plane Migration (Live CPM)&quot;">​</a></h1><ul><li>📌 <strong>GEP Tracking Issue:</strong> <a href="https://github.com/gardener/enhancements/issues/39" target="_blank" rel="noreferrer">https://github.com/gardener/enhancements/issues/39</a></li><li>📖 <strong>GEP Link:</strong> <a href="https://github.com/gardener/enhancements/tree/main/geps/0039-live-control-plane-migration" target="_blank" rel="noreferrer">https://github.com/gardener/enhancements/tree/main/geps/0039-live-control-plane-migration</a></li><li>✍🏻 <strong>Author(s):</strong> <a href="https://github.com/acumino" target="_blank" rel="noreferrer">@acumino</a> Sonu Kumar Singh, <a href="https://github.com/ary1992" target="_blank" rel="noreferrer">@ary1992</a> Ashish Ranjan Yadav, <a href="https://github.com/seshachalam-yv" target="_blank" rel="noreferrer">@seshachalam-yv</a> Seshachalam, <a href="https://github.com/shafeeqes" target="_blank" rel="noreferrer">@shafeeqes</a> Shafeeque E S</li><li>🗓️ <strong>Presentation:</strong> 2026-02-09, 13:00 - 14:00 CET</li><li>🎥 <strong>Recording:</strong> <a href="https://youtu.be/DdU8SNNf23o" target="_blank" rel="noreferrer">https://youtu.be/DdU8SNNf23o</a></li><li>👨‍⚖️ <strong>Decisions:</strong><ul><li>No major technical decisions were finalized in this session.</li><li>Agreement to: <ul><li><strong>Revamp and update the proposal document</strong>, addressing the open questions above.</li><li>Clearly document assumptions, risks, and guarantees.</li><li>Hold a <strong>follow-up Technical Steering session in a few weeks</strong> to re-evaluate the updated proposal.</li></ul></li><li><em>Key Discussion Points &amp; Open Questions</em><ul><li><strong>Failure Handling &amp; Recovery</strong><ul><li>What additional failure modes exist beyond those documented (e.g., ETCD scale-up failures)?</li><li>Can we always fall back to <strong>normal CPM</strong>, or are there cases requiring <strong>manual intervention</strong>?</li><li>Assumption: all failures except those explicitly documented should be <strong>retryable / recoverable</strong>.</li><li>Gardenlet restart behavior: <ul><li>Current proposal resumes from the failed step.</li><li>This differs from usual reconciliation semantics (restart from beginning).</li><li>Question: could this lead to <strong>irrecoverable or inconsistent states</strong>?</li></ul></li></ul></li><li><strong>ETCD-related Topics</strong><ul><li><strong>6-member ETCD risk</strong>: <ul><li>3 members per seed implies <strong>permanent quorum loss</strong> if seed-to-seed connectivity is lost.</li></ul></li><li><strong>ETCD APIs</strong>: <ul><li>Separate APIs exist for member name prefix vs. externally managed members due to uniqueness constraints.</li><li>Question: can these be harmonized, or would that increase complexity?</li></ul></li><li><strong>ETCD member removal</strong>: <ul><li>GEP-28 (SHSC) requires this as well.</li><li>Existing plan: <code>etcd-druid</code> removes members via HTTP calls to the backup-restore sidecar.</li><li>Question: can Live CPM reuse this approach instead of introducing <code>EtcdOpsTask</code>?</li></ul></li><li><strong>ETCD exposure</strong>: <ul><li>Proposal doc is outdated and will be updated to reflect <strong>Istio-based exposure</strong>.</li><li>Open question: how are <code>DNSRecord</code>s constructed in this model?</li></ul></li></ul></li><li><strong>Networking &amp; Connectivity</strong><ul><li>Is <strong>seed-to-seed connectivity</strong> guaranteed at all times?</li><li>VPN setup: <ul><li>Why is an additional VPN seed server configuration needed on the destination seed?</li><li>Can we deploy directly in the “target” configuration from the start?</li></ul></li></ul></li><li><strong>Scheduling &amp; Latency Constraints</strong><ul><li>Scheduler <code>ConfigMap</code> distances are <strong>weights</strong>, not necessarily latency in ms.</li><li>How is the <strong>“distant region” prevention</strong> for LCPM enforced?</li><li>The proposal should explain how the <strong>180 ms latency threshold</strong> was derived.</li></ul></li><li><strong>Control Plane Components &amp; Coordination</strong><ul><li><strong>Lease management</strong>: <ul><li>Can controllers simply be recreated in the destination seed instead of running in both seeds?</li><li>Would this simplify the implementation / should we change the proposal?</li></ul></li><li><strong>Gardenlet coordination</strong>: <ul><li>Current design uses back-and-forth updates via <code>.status.liveMigration</code>.</li><li>Question: would <strong>conditions</strong> be a clearer and more robust coordination mechanism?</li></ul></li><li><strong>Gardenlet versions</strong>: <ul><li>How is it enforced that gardenlets in both seeds run the <strong>same version</strong>?</li><li>What happens if a gardenlet upgrade occurs while a migration is already in progress?</li></ul></li></ul></li><li><strong>Autoscaling &amp; Resource Management</strong><ul><li><strong>VPA recommendations</strong>: <ul><li>Not yet considered.</li><li>Open question: do <code>VPACheckpoint</code>s need to be transferred as part of migration?</li></ul></li></ul></li></ul></li></ul></li></ul>',2)]))}const h=t(r,[["render",l]]);export{m as __pageData,h as default};
